class Solution { private int[] balls;private int half;private double[][] choose;private double dfs(int color,int used,int distinctFirst,int distinctSecond,double ways){if(used>half)return 0;if(color==balls.length)return used==half&&distinctFirst==distinctSecond?ways:0;double answer=0;for(int take=0;take<=balls[color];take++)answer+=dfs(color+1,used+take,distinctFirst+(take>0?1:0),distinctSecond+(take<balls[color]?1:0),ways*choose[balls[color]][take]);return answer;}public double getProbability(int[] balls){this.balls=balls;int total=Arrays.stream(balls).sum();half=total/2;choose=new double[total+1][total+1];for(int n=0;n<=total;n++){choose[n][0]=choose[n][n]=1;for(int k=1;k<n;k++)choose[n][k]=choose[n-1][k-1]+choose[n-1][k];}return dfs(0,0,0,0,1.0)/choose[total][half];} }
